import{_ as l,C as a,o as c,c as i,j as t,a as d,E as n,a2 as r}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"SDF 字形图集与文本排版渲染 (dev.anvilcraft.lib.v2.font.sdf)","description":"","frontmatter":{},"headers":[],"relativePath":"26.1/font/sdf-renderer.md","filePath":"26.1/font/sdf-renderer.md"}'),s={name:"26.1/font/sdf-renderer.md"};function f(x,e,u,g,p,y){const o=a("BranchContextCard");return c(),i("div",null,[e[0]||(e[0]=t("h1",{id:"sdf-字形图集与文本排版渲染-dev-anvilcraft-lib-v2-font-sdf",tabindex:"-1"},[d("SDF 字形图集与文本排版渲染 ("),t("code",null,"dev.anvilcraft.lib.v2.font.sdf"),d(") "),t("a",{class:"header-anchor",href:"#sdf-字形图集与文本排版渲染-dev-anvilcraft-lib-v2-font-sdf","aria-label":'Permalink to "SDF 字形图集与文本排版渲染 (`dev.anvilcraft.lib.v2.font.sdf`)"'},"​")],-1)),n(o,{branch:"26.1"}),e[1]||(e[1]=r('<p>本篇深入解析 <code>module.font</code> 的底层 SDF（Signed Distance Field，有向距离场）字形生成算法、分页图集动态管理、文本布局缓存以及 26.1 GUI 渲染状态提交管线。</p><hr><h2 id="一、-sdf-文本渲染管线工作原理" tabindex="-1">一、 SDF 文本渲染管线工作原理 <a class="header-anchor" href="#一、-sdf-文本渲染管线工作原理" aria-label="Permalink to &quot;一、 SDF 文本渲染管线工作原理&quot;">​</a></h2><ol><li><strong>虚拟线程异步字形光栅化与 EDT 距离场计算 (<code>SdfGlyphAtlas</code>)</strong>： <ul><li>每个 <code>java.awt.Font</code>（按 <code>fontName.style.size</code> 唯一标识，字号不足 4 时自动派生为 <code>64px</code> 高清字号）对应一个 <code>SdfGlyphAtlas</code> 实例；</li><li>图集初始化时预先同步生成 ASCII <code>32 ~ 126</code> 常用字符；当渲染遇到中文、日文或符号等非 ASCII 码点时，<code>atlas.glyph(codepoint, ...)</code> 会立即返回 <code>null</code>（当前帧暂按半字宽留白推进，绝不阻塞主渲染线程），同时将该码点投入 <code>AnvilLib-SDF-Glyph-*</code> 虚拟线程后台生成；</li><li>在后台线程中，先用 AWT <code>Graphics2D</code> 将字符绘制为白底透明抗锯齿掩码，再通过两遍扫描的 <strong>Dead Reckoning 欧氏距离变换（EDT）</strong> 计算每个像素到最近字形边缘的有向距离 <code>signed</code>，归一化到 <code>[0, 255]</code> 灰度值写入 <code>SdfGlyphPage</code>（<code>0.5</code> 即 <code>128</code> 对应字形轮廓边界），并在单元格四周填充 <code>padding</code> 边缘延展像素防止双线性插值越界采样。</li><li>后台字形生成完毕后，自动递增 <code>SdfGlyphPage.version</code> 并调用 <code>SdfTextLayout.invalidateAtlas(key)</code> 使布局缓存失效，下一帧即可直接显示新字形。</li></ul></li><li><strong>按需脏页上传至单通道 GPU 纹理 (<code>SdfAtlasTexture</code> &amp; <code>SdfGlyphPage</code>)</strong>： <ul><li>每个 <code>SdfGlyphPage</code> 尺寸为 <code>1024 × 1024</code>。在每帧绘制前，<code>SdfAtlasTexture.ensureUploaded(atlas)</code> 检查所有页面的 <code>dirty</code> 与 <code>version</code> 原子版本号；若有更新，则将其上传为 <code>TextureFormat.RED8</code> 单通道 GPU 纹理，并绑定 <code>FilterMode.LINEAR</code> 线性采样器。</li></ul></li><li><strong>按图集页分桶的 CPU 排版缓存 (<code>SdfTextLayout</code>)</strong>： <ul><li><code>SdfTextLayout.fromAtlas(atlas, text, x, y, scale)</code> 将字符串中的码点转换为相对于原点 <code>(0, 0)</code> 的 <code>GlyphQuad</code> 矩形，并按所属的 <code>pageIndex</code> 分桶组装为 <code>List&lt;PageQuads&gt;</code>；</li><li>当一段文本的所有码点均已在图集中就绪（<code>allGlyphsAvailable == true</code>）时，排版结果以 <code>(atlasKey, text, round(scale * 1000))</code> 为键存入最大容量 <code>1024</code> 的 <code>LAYOUT_CACHE</code>。</li></ul></li><li><strong>提交 GUI 渲染状态 (<code>SdfTextRenderer</code> &amp; <code>SdfTextRenderState</code>)</strong>： <ul><li><code>SdfTextRenderer</code> 解析 <code>FormattedCharSequence</code> 中的颜色、粗斜体（自动切换 <code>base.deriveFont(mask)</code>）、下划线/删除线与混淆样式（每 <code>300 ms</code> 变换随机 ASCII 字符），将每个 <code>PageQuads</code> 封装为实现 <code>LibGuiElementRenderState</code> 的 <code>SdfTextRenderState</code>，调用 <code>graphics.submitGuiElementRenderState(state)</code> 提交至 Minecraft 26.1 的 GUI 渲染管线。</li></ul></li></ol><hr><h2 id="二、-类与-api-详解" tabindex="-1">二、 类与 API 详解 <a class="header-anchor" href="#二、-类与-api-详解" aria-label="Permalink to &quot;二、 类与 API 详解&quot;">​</a></h2><h3 id="_1-sdftextrenderer-sdf-文本渲染器-beta" tabindex="-1">1. <code>SdfTextRenderer</code>（SDF 文本渲染器，<code>@Beta</code>） <a class="header-anchor" href="#_1-sdftextrenderer-sdf-文本渲染器-beta" aria-label="Permalink to &quot;1. `SdfTextRenderer`（SDF 文本渲染器，`@Beta`）&quot;">​</a></h3><p>位于 <code>dev.anvilcraft.lib.v2.font.sdf.SdfTextRenderer</code>。通常通过 <code>GuiGraphicsExtractor#anvillib$textRenderer()</code> 获取，也可直接实例化使用。</p><table tabindex="0"><thead><tr><th style="text-align:left;">构造器 / 方法签名</th><th style="text-align:left;">参数与行为说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public SdfTextRenderer()</code></td><td style="text-align:left;">创建渲染器并绑定 <code>FilterMode.LINEAR</code> 边缘钳制采样器。</td></tr><tr><td style="text-align:left;"><code>public void drawString(GuiGraphicsExtractor graphics, @Nullable Font font, @Nullable String text, int x, int y, int color, boolean dropShadow)</code></td><td style="text-align:left;">使用 <code>font</code>（为 <code>null</code> 时回退 <code>Dialog</code> 64px）在 <code>(x, y)</code> 绘制纯文本字符串。若 <code>text</code> 为 <code>null</code> 或空串则直接返回。</td></tr><tr><td style="text-align:left;"><code>public void drawComponent(GuiGraphicsExtractor graphics, @Nullable Font font, Component text, int x, int y, int color, boolean dropShadow)</code></td><td style="text-align:left;">将 <code>Component</code> 转为 <code>text.getVisualOrderText()</code> 后委托 <code>drawFormatted</code> 绘制。</td></tr><tr><td style="text-align:left;"><code>public void drawFormatted(GuiGraphicsExtractor graphics, @Nullable Font font, FormattedCharSequence text, int x, int y, int color, boolean dropShadow)</code></td><td style="text-align:left;">按字符遍历 <code>FormattedCharSequence</code>：<br>• 支持 <code>style.isObfuscated()</code> 动态随机字符混淆；<br>• 当颜色、<code>bold</code> 或 <code>italic</code> 发生变化时自动分段刷出（<code>flushFormattedSegment</code>）并派生对应字重 <code>Font</code>；<br>• 支持 <code>style.isUnderlined()</code> 与 <code>style.isStrikethrough()</code>，通过 <code>0.5f</code> Y 轴缩放绘制高精度细下划线与删除线。</td></tr><tr><td style="text-align:left;"><code>public void drawWrapped(GuiGraphicsExtractor graphics, @Nullable Font font, FormattedText text, int x, int y, int width, int color, boolean dropShadow)</code></td><td style="text-align:left;">使用 <code>ALFont.wrapLines</code> 将 <code>text</code> 按最大宽度 <code>width</code> 折行后，按 <code>lineHeight</code> 行距逐行绘制。</td></tr><tr><td style="text-align:left;"><code>public void drawCentered(GuiGraphicsExtractor graphics, @Nullable Font font, Component text, int x, int y, int color)</code></td><td style="text-align:left;">测量 <code>Component</code> 视觉文本总宽度并以 <code>x</code> 为中心调用 <code>drawFormatted</code> 绘制。</td></tr><tr><td style="text-align:left;"><code>public void drawCentered(GuiGraphicsExtractor graphics, @Nullable Font font, FormattedCharSequence text, int x, int y, int color)</code></td><td style="text-align:left;">测量 <code>FormattedCharSequence</code> 总宽度并以 <code>x</code> 为中心调用 <code>drawFormatted</code> 绘制。</td></tr></tbody></table><h3 id="_2-sdfglyphatlas-多页按需-sdf-字形图集-apistatus-internal" tabindex="-1">2. <code>SdfGlyphAtlas</code>（多页按需 SDF 字形图集，<code>@ApiStatus.Internal</code>） <a class="header-anchor" href="#_2-sdfglyphatlas-多页按需-sdf-字形图集-apistatus-internal" aria-label="Permalink to &quot;2. `SdfGlyphAtlas`（多页按需 SDF 字形图集，`@ApiStatus.Internal`）&quot;">​</a></h3><p>位于 <code>dev.anvilcraft.lib.v2.font.sdf.SdfGlyphAtlas</code>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方法 / 记录签名</th><th style="text-align:left;">返回值</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public static CompletableFuture&lt;SdfGlyphAtlas&gt; getOrCreate(@Nullable Font font)</code></td><td style="text-align:left;"><code>CompletableFuture&lt;SdfGlyphAtlas&gt;</code></td><td style="text-align:left;">在后台虚拟线程池中异步构建（或从缓存获取）指定 <code>Font</code> 的 SDF 图集 Future。</td></tr><tr><td style="text-align:left;"><code>public static @Nullable SdfGlyphAtlas getIfReady(@Nullable Font font)</code></td><td style="text-align:left;"><code>@Nullable SdfGlyphAtlas</code></td><td style="text-align:left;">非阻塞获取图集：若后台已构建完成则返回实例；若仍在构建中则返回 <code>null</code>；若此前构建异常失败则自动移除失败 Future 并重新触发构建。</td></tr><tr><td style="text-align:left;"><code>public String key()</code> / <code>public Font font()</code></td><td style="text-align:left;"><code>String</code> / <code>Font</code></td><td style="text-align:left;">获取图集唯一键（<code>&lt;fontName&gt;.&lt;style&gt;.&lt;size&gt;</code>）与解析后的 <code>64px</code> <code>Font</code>。</td></tr><tr><td style="text-align:left;"><code>public int awtHeight()</code> / <code>public int awtAscent()</code></td><td style="text-align:left;"><code>int</code></td><td style="text-align:left;">获取 AWT 字体在图集字号下的总高度与基线上升高度（Ascent）。</td></tr><tr><td style="text-align:left;"><code>public int pageCount()</code> / <code>public SdfGlyphPage page(int index)</code></td><td style="text-align:left;"><code>int</code> / <code>SdfGlyphPage</code></td><td style="text-align:left;">获取当前已分配的 <code>1024×1024</code> 图集页数量及指定页对象。</td></tr><tr><td style="text-align:left;"><code>public @Nullable GlyphEntry glyph(int codepoint, Consumer&lt;SdfGlyphPage&gt; pageConsumer)</code></td><td style="text-align:left;"><code>@Nullable GlyphEntry</code></td><td style="text-align:left;">查询指定 Unicode 码点的字形条目。若尚未生成，自动提交虚拟线程任务异步生成并返回 <code>null</code>。</td></tr><tr><td style="text-align:left;"><code>public int measureText(String text)</code> / <code>measureText(String text, int start, int end)</code></td><td style="text-align:left;"><code>int</code></td><td style="text-align:left;">测量字符串或子串在图集像素坐标系下的总步进宽度（<code>advance</code> 之和；未就绪字形暂按 <code>cellSize / 2</code> 计）。</td></tr><tr><td style="text-align:left;"><code>public int measureCodepoint(int codepoint)</code></td><td style="text-align:left;"><code>int</code></td><td style="text-align:left;">测量单个码点在图集像素坐标系下的步进宽度。</td></tr><tr><td style="text-align:left;"><code>public record GlyphEntry(int pageIndex, int atlasX, int atlasY, int width, int height, int advance)</code></td><td style="text-align:left;"><code>record</code></td><td style="text-align:left;">记录单个字形所在的图集页索引、页内左上角坐标 <code>(atlasX, atlasY)</code>、宽高（含 <code>endX()</code> / <code>endY()</code> 计算方法）与水平步进 <code>advance</code>。</td></tr></tbody></table><h3 id="_3-sdfglyphpage、sdfatlastexture、sdftextlayout-与-sdftextrenderstate-apistatus-internal" tabindex="-1">3. <code>SdfGlyphPage</code>、<code>SdfAtlasTexture</code>、<code>SdfTextLayout</code> 与 <code>SdfTextRenderState</code>（<code>@ApiStatus.Internal</code>） <a class="header-anchor" href="#_3-sdfglyphpage、sdfatlastexture、sdftextlayout-与-sdftextrenderstate-apistatus-internal" aria-label="Permalink to &quot;3. `SdfGlyphPage`、`SdfAtlasTexture`、`SdfTextLayout` 与 `SdfTextRenderState`（`@ApiStatus.Internal`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类名</th><th style="text-align:left;">核心方法签名</th><th style="text-align:left;">职责说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SdfGlyphPage</code></td><td style="text-align:left;"><code>public void updateHash()</code></td><td style="text-align:left;">维护单张 <code>1024×1024</code> <code>TYPE_BYTE_GRAY</code> 灰度缓冲图像、网格行列游标与 <code>AtomicInteger version</code> 版本号。</td></tr><tr><td style="text-align:left;"><code>SdfAtlasTexture</code></td><td style="text-align:left;"><code>public static Identifier uploadPage(SdfGlyphAtlas atlas, int pageIndex)</code><br><code>public static void ensureUploaded(SdfGlyphAtlas atlas)</code></td><td style="text-align:left;">将脏页原子转换为 <code>NativeImage</code> 并上传为 <code>TextureFormat.RED8</code> + <code>FilterMode.LINEAR</code> 的 GPU 纹理，注册到 <code>Minecraft.getInstance().getTextureManager()</code>（纹理路径形如 <code>anvillib_font:dynamic/sdf_atlas/&lt;sanitized_key&gt;</code>）。</td></tr><tr><td style="text-align:left;"><code>SdfTextLayout</code></td><td style="text-align:left;"><code>public static SdfTextLayout fromAtlas(SdfGlyphAtlas atlas, @Nullable String text, int x, int y, float scale)</code><br><code>public static void invalidateAtlas(String atlasKey)</code><br><code>public static void clearCache()</code><br><code>public List&lt;PageQuads&gt; pages()</code><br><code>public int width()</code> / <code>public int height()</code></td><td style="text-align:left;">计算并缓存字符串的字形四边形集合。包含公开记录 <code>PageQuads(int pageIndex, @Nullable Identifier atlasTexture, int pageWidth, int pageHeight, List&lt;GlyphQuad&gt; quads)</code> 与 <code>GlyphQuad(int x0, int y0, int x1, int y1, float u0, float v0, float u1, float v1, char glyph)</code>。</td></tr><tr><td style="text-align:left;"><code>SdfTextRenderState</code></td><td style="text-align:left;"><code>public record SdfTextRenderState(...) implements LibGuiElementRenderState</code></td><td style="text-align:left;">实现 <code>module.rendering</code> 的 <code>LibGuiElementRenderState</code>，绑定 <code>ALFPipelines.SDF_TEXT</code> 管线与 <code>DiffuseSampler</code> 图集纹理，在 <code>buildVertices</code> 中使用 <code>consumer.addVertexWith2DPose</code> 提交字形四边形顶点，并通过 <code>LibGuiElementRenderState.getBounds</code> 计算裁剪边界。</td></tr></tbody></table>',14))])}const S=l(s,[["render",f]]);export{b as __pageData,S as default};
